const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const items = $input.all();

const requiredFields = [
  "Request_ID",
  "Customer_ID",
  "Customer_Name",
  "Customer_Email",
  "Order_ID",
  "Refund_Reason",
  "Product_Category",
  "Order_Amount",
  "Days_Since_Order",
  "Previous_Refunds"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const orderAmount =
    Number(data.Order_Amount);

  const daysSinceOrder =
    Number(data.Days_Since_Order);

  const previousRefunds =
    Number(data.Previous_Refunds);

  if (
    missingFields.length === 0 &&
    !isNaN(orderAmount) &&
    !isNaN(daysSinceOrder) &&
    !isNaN(previousRefunds) &&
    orderAmount >= 0 &&
    daysSinceOrder >= 0 &&
    previousRefunds >= 0
  ) {

    validItems.push({
      ...data,

      Order_Amount:
        orderAmount,

      Days_Since_Order:
        daysSinceOrder,

      Previous_Refunds:
        previousRefunds
    });

  } else {

    invalidItems.push({
      request_id:
        data.Request_ID || "Unknown",

      missing_fields:
        missingFields
    });
  }
}

return [
  {
    json: {

      data_valid:
        invalidItems.length === 0,

      total_requests:
        items.length,

      valid_requests:
        validItems.length,

      invalid_requests:
        invalidItems.length,

      invalid_details:
        invalidItems,

      refund_data:
        validItems
    }
  }
];

const requests = $json.refund_data;

const analyzedRequests = [];

for (const request of requests) {

  const amount =
    Number(request.Order_Amount);

  const days =
    Number(request.Days_Since_Order);

  const previousRefunds =
    Number(request.Previous_Refunds);

  let reviewScore = 0;

  // Refund amount
  if (amount >= 10000) {
    reviewScore += 3;
  } else if (amount >= 5000) {
    reviewScore += 2;
  } else {
    reviewScore += 1;
  }

  // Order age
  if (days > 30) {
    reviewScore += 3;
  } else if (days > 15) {
    reviewScore += 2;
  }

  // Previous refunds
  if (previousRefunds >= 3) {
    reviewScore += 3;
  } else if (previousRefunds >= 1) {
    reviewScore += 1;
  }

  let initialPriority;

  if (reviewScore >= 6) {
    initialPriority = "HIGH";
  } else if (reviewScore >= 3) {
    initialPriority = "MEDIUM";
  } else {
    initialPriority = "LOW";
  }

  analyzedRequests.push({
    ...request,

    Review_Score:
      reviewScore,

    Initial_Priority:
      initialPriority
  });
}

return [
  {
    json: {
      analyzed_refunds:
        analyzedRequests
    }
  }
];

